  <nav class="navigation" aria-label="Main navigation"><div class="tabs" role="tablist">${[[`library`,`Presets`],[`reset`,`Reset`],[`parameters`,`Param`],[`midi`,`MIDI`],[`settings`,`⚙`],[`player`,`♫`]].map(([e,t])=>`<button class="tab" id="tab-${e}" data-tab="${e}" role="tab" aria-selected="false" aria-label="${e===`settings`?`Preferences`:e===`player`?`MIDI file player`:t}" title="${e===`settings`?`Preferences`:e===`player`?`MIDI file player`:t}" aria-controls="view-${e}">${e===`settings`?_(`gear`):e===`player`?_(`music`):t}</button>`).join(``)}</div></nav>
